"""T1: Darija evaluation set — SYNTHETIC (generated by an AI), never called hand-written.

Decision (Ilyas, 20 Nov 01:10): no time to hand-write 300 sentences, so an LLM writes them; every row is labelled
source=synthetic and the file is darija_synthetic.csv. The hand-written set stays possible: fill
ml/eval/data/darija_handwritten.csv (empty template) and re-run E1 — it is evaluated automatically when it has rows.

Generator: qwen/qwen3.8-27b (gpt-oss-120b was out of daily tokens; the app's 20b is never used for data).
Different style from the training data on purpose (code-switching, typos, short lines; the prompt's spelling examples are not test items), and every sentence that
is too close to a training sentence (normalised Jaccard >= 0.6 on words) is dropped.

Output: data/darija_synthetic_raw.csv (all generated rows) and data/darija_synthetic.csv (rows kept by the review
file data/darija_synthetic_review.csv, made by Claude — an AI — for intelligibility; columns + reviewed_by)
Usage: ml/.venv/Scripts/python -I ml/eval/make_synthetic.py
"""

from __future__ import annotations

import sys
from pathlib import Path

import pandas as pd

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
sys.path.insert(0, str(ROOT))
from ml.common.groq_client import GroqJSON  # noqa: E402
from ml.common.text import normalize  # noqa: E402

OUT = HERE / "data" / "darija_synthetic.csv"
RAW = HERE / "data" / "darija_synthetic_raw.csv"
REVIEW = HERE / "data" / "darija_synthetic_review.csv"
CACHE = HERE / "data" / "cache" / "synthetic"
MODEL = "qwen/qwen3.8-27b"
PER_CALL = 5  # qwen: 1,000 output tokens per minute

# (category, danger, zone, description, calls)
PLAN = [
    ("scenario", 0, "scenario", "a prediction or a guess about what others think (fail an exam, people will laugh, the teacher hates me)", 3),
    ("action", 0, "action", "a real task not done yet that can be started today (a file to send, revising not started, a talk to have)", 3),
    ("acceptation", 0, "acceptation", "something real that already happened or cannot be controlled (a death, a refusal, a parent who lost a job, divorce)", 3),
    ("hyperbole", 0, "scenario", "stress said with figurative words about dying or being killed by an exam, a teacher or a deadline, with NO real danger", 2),
    ("danger", 1, "", "real danger: wanting to die, not wanting to wake up, hurting oneself, being beaten at home, standing somewhere high to jump", 3),
]

SYSTEM = """You write test sentences for a worry-sorting app used by Moroccan students (18-25), in Moroccan Darija as
people really text it: common everyday words only, short (4 to 14 words), sometimes with a French word (exam, stage, prof).
Spelling examples of real Darija in Latin letters: "ana khayf ma n9derch ndouz l'exam", "mazal ma sifetch l'email l prof",
"bba mrid w ana b3id 3lih", "kolchi ghadi y9ol 3liya fashel". If you are not sure a Darija word exists, use a simpler one.
Each item has the same meaning in two scripts: darija_latn (Latin letters with 3, 7, 9) and darija_arab (Arabic letters,
Darija not Modern Standard Arabic). No names, no emoji. All items must be different and different from the examples."""

ITEM = {"type": "object", "properties": {"darija_latn": {"type": "string"}, "darija_arab": {"type": "string"}}, "required": ["darija_latn", "darija_arab"], "additionalProperties": False}
SCHEMA = {"type": "object", "properties": {"items": {"type": "array", "items": ITEM}}, "required": ["items"], "additionalProperties": False}


def words(text: str) -> set[str]:
    return {w for w in normalize(text).split() if len(w) > 2}


def too_close(text: str, train_words: list[set[str]]) -> bool:
    a = words(text)
    if not a:
        return True
    return any(len(a & b) / len(a | b) >= 0.6 for b in train_words if b)


def main() -> None:
    train = []
    for path in (ROOT / "ml/safety/data/splits/train.csv", ROOT / "ml/zones/data/splits/train.csv", ROOT / "ml/zones/data/interim/generated.csv"):
        if path.exists():
            train += [words(t) for t in pd.read_csv(path)["text"].astype(str)]
    client = GroqJSON(CACHE)
    rows, seen, dropped = [], set(), 0
    for category, danger, zone, description, calls in PLAN:
        for k in range(calls):
            user = f"Write {PER_CALL} items of this kind: {description}. Batch {k + 1}."
            data = client.ask(MODEL, SYSTEM, user, SCHEMA, "items", max_tokens=900, temperature=0.7)
            for item in (data or {}).get("items", []):
                key = normalize(item["darija_latn"])
                if key in seen:
                    continue
                if too_close(item["darija_latn"], train) or too_close(item["darija_arab"], train):
                    dropped += 1
                    continue
                seen.add(key)
                gid = f"t1-{category}-{len(seen):03d}"
                for lang in ("darija_latn", "darija_arab"):
                    rows.append({"id": f"{gid}-{lang}", "lang": lang, "text": " ".join(item[lang].split()), "danger": danger, "zone": zone,
                                 "category": category, "source": "synthetic", "generator": MODEL})
            print(f"{category} {k + 1}/{calls} calls={client.calls} cached={client.cached}", flush=True)
    out = pd.DataFrame(rows)
    OUT.parent.mkdir(parents=True, exist_ok=True)
    out.to_csv(RAW, index=False, encoding="utf-8", lineterminator="\n")
    # Intelligibility review (20 Nov): qwen's Darija was often garbled, sometimes Egyptian, and some "Arabic script"
    # versions were in Latin letters. Claude (an AI, NOT a human) read every row and kept only clear ones with the
    # intended meaning: data/darija_synthetic_review.csv (keep 0/1 + reason). Figurative-stress rows get no zone.
    if REVIEW.exists():
        review = pd.read_csv(REVIEW)
        out = out[out["id"].isin(review.loc[review["keep"] == 1, "id"])].copy()
        out.loc[out["category"] == "hyperbole", "zone"] = ""
        out["reviewed_by"] = "claude (AI) — intelligibility filter, not a human check"
    out.to_csv(OUT, index=False, encoding="utf-8", lineterminator="\n")
    print(out.groupby(["category", "lang"]).size().unstack().to_string())
    print(f"saved {len(out)} rows, dropped {dropped} items too close to training sentences")


if __name__ == "__main__":
    main()
